import{_ as r,l as i,o as e,c as n,v as t,p as s,x as o,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"VALL-E 式 TTS","description":"","frontmatter":{"title":"VALL-E 式 TTS","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/valle-tts.md","filePath":"llm/valle-tts.md","lastUpdated":1789023840000}'),A={name:"llm/valle-tts.md"};function h(E,a,m,T,_,L){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="vall-e-式-tts" tabindex="-1">VALL-E 式 TTS <a class="header-anchor" href="#vall-e-式-tts" aria-label="Permalink to &quot;VALL-E 式 TTS&quot;">​</a></h1><div class="epigraph"><p>语音也可以是 codec 下标。给三秒提示音加文本，语言模型在离散声学 token 上续写，零样本克隆音色。</p><footer>—— Wang 等 Neural Codec Language Models are Zero-Shot Text to Speech Synthesizers（VALL-E）；码流见 Défossez 等 EnCodec</footer></div><p><a href="/llm/video-gen-spatiotemporal">上一课</a>收束像素生成。本单元问说与听。图像侧 <a href="/llm/vqgan">VQGAN</a> 把图变成码；语音侧神经 codec 把波形变成多码本下标。缺口是把 TTS 写成 in-context 语言模型，而不是再训说话人嵌入流水线。后课全双工默认：VALL-E 仍是一轮合成，不是边听边说。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传统 TTS：文本分析 → 声学模型 → 声码器，换说话人要数据。EnCodec 等 RVQ 把波形压成若干层离散码。VALL-E 把「提示语音的码 + 音素或文本」当前缀，自回归预测目标句的 codec token，再解码成波。零样本来自上下文：音色在提示码里，不必显式 ID。</p><p>与 <a href="/llm/clip">CLIP</a> 无关：这里没有图文空间。和文本 LLM 同构的是损失：码上的 CE。</p><p><span class="marginnote">RVQ 多层码不能天真地当单一词表：粗层先决定内容，细层补残差。VALL-E 用分层 AR / 非 AR 组合，而不是一个扁平 softmax 包打天下。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>训练：大规模语音的 codec 语言建模，条件为文本对齐。推理：提示波 → codec，与文本拼接，采样码 → codec 解码。评测：说话人相似度、WER、自然度；不要用图像 FID。安全：零样本克隆可被滥用，产品必须验证授权，这是后课 omni 对齐的前奏。</p>',9)),(e(),s(p,null,{default:o(()=>[c(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PR%5B%22%E6%8F%90%E7%A4%BA%E8%AF%AD%E9%9F%B3%22%5D%20--%3E%20C%5B%22codec%20%E7%A0%81%22%5D%0A%20%20TXT%5B%22%E6%96%87%E6%9C%AC%22%5D%20--%3E%20LM%5B%22codec%20%E8%AF%AD%E8%A8%80%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20C%20--%3E%20LM%0A%20%20LM%20--%3E%20WAV%5B%22%E8%A7%A3%E7%A0%81%E6%B3%A2%E5%BD%A2%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>提示码提供说话人与声学条件，文本提供内容。LM 若更跟提示的内容而非音色，就会内容泄漏或音色漂。分层码让内容主要走粗 token，类似图像金字塔把布局放粗层。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>合成是离线、单向的。下一课 Moshi 把听与说叠在同一时间轴上。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>VALL-E 把 TTS 写成 codec token 上的零样本语言模型。</li><li>音色在提示上下文里，不是分类说话人 ID。</li><li>多层 RVQ 要分层建模。</li><li>出处：Wang 等 VALL-E；EnCodec。</li></ul>',6))])}const V=r(A,[["render",h]]);export{u as __pageData,V as default};
